], ['id', 'niss', 'birthday'])
inconsistent_employee_ids = [row['id'] for row in inconsistent_employees if row['birthday'] and row['niss'] and _do_birthday_and_niss_disagree(row['birthday'], row['niss'])]
if inconsistent_employee_ids:
    warning_records = self.env['hr.employee'].browse(inconsistent_employee_ids)

