max_meal_vouchers = 220
warning_records = self.env['hr.payslip']
warning_details = defaultdict(list)

employee_year_pairs = {(p.employee_id.id, p.date_from.year) for p in payslips}
years = {year for _, year in employee_year_pairs}
year_payslips_all = self.env['hr.payslip']
if years:
    year_payslips_all = self.env['hr.payslip'].search([
        ('employee_id', 'in', payslips.employee_id.ids),
        ('date_from', '>=', date(min(years), 1, 1)),
        ('date_from', '<=', date(max(years), 12, 31)),
    ])

meal_voucher_values = year_payslips_all._get_line_values(
    ['MEAL_V_EMP'], vals_list=['quantity']
)['MEAL_V_EMP']

meal_vouchers_per_employee_year = {}
for yp in year_payslips_all:
    key = (yp.employee_id.id, yp.date_from.year)
    if key in employee_year_pairs:
        qty = meal_voucher_values.get(yp.id, {}).get('quantity', 0)
        meal_vouchers_per_employee_year[key] = meal_vouchers_per_employee_year.get(key, 0) + qty

for payslip in payslips:
    key = (payslip.employee_id.id, payslip.date_from.year)
    if meal_vouchers_per_employee_year.get(key, 0) > max_meal_vouchers:
        warning_records |= payslip
        warning_details[payslip].append({
            'message': _get_payroll_translation("Meal vouchers exceed annual limit (%(max_count)s).", max_count=max_meal_vouchers),
            'level': 'warning',
        })

payslips = records.filtered(lambda p:
    p.state == 'draft'
    and p.company_id.country_id.code == 'BE'
    and p.struct_id.code == 'BEMONTHLY'
    and p.version_id.ip_wage_rate > 0)
# the yearly limit only exists since 2026
limit_by_payslip = {}
for payslip in payslips:
    limit = self.env['hr.rule.parameter']._get_parameter_from_code('ip_limit', payslip.date_to, raise_if_not_found=False)
    if limit:
        limit_by_payslip[payslip] = limit
payslips = payslips.filtered(lambda p: p in limit_by_payslip)
warning_records = self.env['hr.payslip']
warning_details = defaultdict(list)
if payslips:
    years = {p.date_to.year for p in payslips}
    # IP of the validated/paid payslips of the year per employee and IP of the checked payslips,
    # in one grouped query
    year_ip_totals = defaultdict(float)
    current_ip_totals = defaultdict(float)
    for employee, year_start, slip, total in self.env['hr.payslip.line']._read_group([
        ('employee_id', 'in', payslips.employee_id.ids),
        ('code', '=', 'IP'),
        ('date_to', '>=', date(min(years), 1, 1)),
        ('date_to', '<=', date(max(years), 12, 31)),
        '|', ('slip_id', 'in', payslips.ids), ('slip_id.state', 'in', ('validated', 'paid')),
    ], ['employee_id', 'date_to:year', 'slip_id'], ['total:sum']):
        if slip in payslips:
            current_ip_totals[slip] += total
        else:
            year_ip_totals[employee.id, year_start.year] += total
    for payslip, limit in limit_by_payslip.items():
        # the IP is capped on the limit by the payslip computation
        year_total = year_ip_totals[payslip.employee_id.id, payslip.date_to.year] + current_ip_totals[payslip]
        if round(year_total, 2) >= round(limit, 2):
            warning_records |= payslip
            warning_details[payslip].append({
                'message': _get_payroll_translation("The intellectual property limit of %(limit)s is reached: the exceeding part is paid as a regular remuneration", limit=payslip.currency_id.format(limit)),
                'level': 'warning',
            })

