company = self.env.company
if company.country_id.code == 'BE' and company.first_payrun_date:
    first_report_year = company.first_payrun_date.year
    reports = self.env['l10n_be.281_xx'].search([
        ('company_id', '=', company.id),
        ('year', '>=', str(first_report_year)),
    ])
    current_year = date.today().year
    for year in range(first_report_year, current_year):
        reports_to_check = reports.filtered(lambda r: r.year == str(year))
        if not reports_to_check or not any(report.state == 'done' for report in reports_to_check):
            report_date = date(year, 1, 1)
            period_payslips = self._check_payslips_for_report(company, report_date, report_date + relativedelta(years=1, days=-1))
            if not period_payslips:
                continue
            warning_records = company
            warning_count = 0
            warning_title = _get_payroll_translation("Tax Forms 281, %(year)s", year=year)
            warning_deadline = date(year, 12, 31) + relativedelta(days=self.warning_offset_days)
            additional_context = {
                'vals': {
                    'year': str(year),
                },
                'model_name': 'l10n_be.281_xx',
            }
            if not reports_to_check:
                warning_button = _get_payroll_translation("Start")
            else:
                warning_button = _get_payroll_translation("Continue")
                additional_context['report_ids'] = reports_to_check.ids
            break

company = self.env.company
if company.country_id.code == 'BE' and company.first_payrun_date:
    first_report_month = company.first_payrun_date.month
    first_report_year = company.first_payrun_date.year
    reports = self.env['l10n_be.274_xx'].search([
        ('company_id', '=', company.id),
        ('year', '>=', first_report_year),
    ])
    first_report_date = date(first_report_year, first_report_month, 1)
    last_report_date = date.today().replace(day=1) - relativedelta(months=1)
    for dt in dateutil.rrule.rrule(dateutil.rrule.MONTHLY, dtstart=first_report_date, until=last_report_date):
        month = dt.month
        year = dt.year
        reports_to_check = reports.filtered(lambda r: r.year == year and r.month == str(month))
        if not reports_to_check or not any(report.state == 'done' for report in reports_to_check):
            report_date = date(year, month, 1)
            period_payslips = self._check_payslips_for_report(company, report_date, report_date + relativedelta(months=1, days=-1))
            if not period_payslips:
                continue
            warning_records = company
            warning_count = 0
            warning_title = _get_payroll_translation("Withholding taxes: %(date)s %(year)s", date=report_date.strftime("%b").capitalize(), year=year)
            warning_deadline = report_date + relativedelta(months=1, days=self.warning_offset_days - 1)
            additional_context = {
                'vals': {
                    'month': str(month),
                    'year': year,
                },
                'model_name': 'l10n_be.274_xx',
            }
            if not reports_to_check:
                warning_button = _get_payroll_translation("Start")
            else:
