if records.state not in ['done', 'paid']:
    payslips = records.payslip_ids
    occupation_data = payslips.mapped('employee_id').version_ids.sorted('date_start', reverse=True)._get_occupation_dates()
    inactive_version_payslips = payslips.filtered(lambda p: not p.version_id.active)
    active_version_payslips = payslips - inactive_version_payslips
    considered_payslips = self.env['hr.payslip']
    invalid_termination_payslips = self.env['hr.payslip']
    for data in occupation_data:
        occupation_contracts, date_from, date_to = data
        payslips = active_version_payslips.filtered(lambda p: p not in considered_payslips and p.version_id in occupation_contracts)
        for slip in inactive_version_payslips:
            if slip not in considered_payslips and slip.date_from < (date_to or quarter_end) and slip.date_to > date_from:
                payslips += slip
        considered_payslips += payslips
        termination_payslips = payslips.filtered(lambda p: p.struct_id.code == 'BETERM')
        if termination_payslips:
            employee = termination_payslips.employee_id
            if not employee.l10n_be_notice_period_start or not employee.departure_date:
                invalid_termination_payslips += termination_payslips

    if invalid_termination_payslips:
        warning_records = invalid_termination_payslips
        warning_details = {
            'message': _get_payroll_translation("Termination payslips missing notice period dates %(names)s", names=", ".join(invalid_termination_payslips.mapped('employee_id.name'))),
            'level': 'danger',
            'action_text': _get_payroll_translation("See payslips"),
            'action': warning_records._get_records_action(),
        }

if records.state not in ['done', 'paid']:
    payslips = records.payslip_ids
    invalid_employees = self.env['hr.employee']

    for emp, emp_payslips in payslips.grouped('employee_id').items():
        student_payslips = emp_payslips.filtered(lambda p: p.version_id.is_student())
        emp_payslips = emp_payslips - student_payslips

        worker_code = False
        if student_payslips:
            worker_code = student_payslips.version_id[0].l10n_be_worker_code_id.dmfa_code
        else:
            worker_code = emp_payslips.version_id[0].l10n_be_worker_code_id.dmfa_code

        if not worker_code:
            invalid_employees |= emp_payslips.employee_id

    if invalid_employees:
        warning_records = invalid_employees
        warning_details = {
            'message': _get_payroll_translation("Employees missing DMFA worker code %(names)s", names=", ".join(invalid_employees.mapped('name'))),
            'level': 'danger',
            'action_text': _get_payroll_translation("See employees"),
            'action': warning_records._get_records_action(),
        }

be_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'BE')
warning_records = self.env['hr.version']
warning_details = defaultdict(list)

versions = self.env['hr.version'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', be_companies.ids),
    ('employee_id', '!=', False),
    ('active', '=', True),
])

for version in versions:
    if version.l10n_be_dimona_category in ('stu', 'flx'):
        continue

    calendar = version.resource_calendar_id
    if calendar._is_flexible():
        continue

    ref_calendar = version._get_reference_calendar()

    if not ref_calendar or ref_calendar.hours_per_week <= 0:
        continue

    rate = round(calendar.hours_per_week / ref_calendar.hours_per_week, 7)

    if rate < 0.10:
        warning_records |= version
        warning_details[version].append({
            'message': _get_payroll_translation(
                "The working schedule is shorter than 10% of the reference full-time calendar. "
                "For a part-time contract, the legal minimum duration is 10%."
            ),
            'level': 'warning',
        })

payslips = self.env['hr.payslip'].search([
    ('company_id', 'in', self.env.companies.filtered(lambda c: c.country_id.code == 'BE').ids)
])
payslips_missing_credit = payslips.filtered(lambda p: p._l10n_be_has_mrt_without_valid_worked_days())
if payslips_missing_credit:
    warning_records = payslips_missing_credit.mapped('employee_id')

employees = self.env['hr.employee'].search([
    ('company_id', 'in', self.env.companies.filtered(lambda c: c.country_id.code == 'BE').ids),
    ('reference_calendar_id', '!=', False),
    ('resource_calendar_id', '!=', False)
])
warning_records = self.env['resource.calendar']
for employee in employees:
    if employee.resource_calendar_id.work_time_rate < 1 and employee.resource_calendar_id.work_time_rate == employee.reference_calendar_id.work_time_rate:
        warning_records |= employee.resource_calendar_id

warning_records = self.env['hr.work.location']
belgian_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'BE')
employees = self.env['hr.employee'].search([('company_id', 'in', belgian_companies.ids)])

for version in employees.version_ids:
    work_location = version.sudo().work_location_id
    if not work_location or work_location.company_id not in belgian_companies:
        continue

    if version.work_location_id.date_start and version.contract_date_start and version.contract_date_start < version.work_location_id.date_start:
        warning_records |= version.work_location_id

payslips = self.env['hr.payslip'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', self.env.companies.ids),
    ('state', '!=', 'cancel'),
])

warning_details = defaultdict(list)
warning_records = self.env['hr.payslip']

for payslip in payslips:
    if not payslip.date_from or not payslip.employee_id:
        continue

    if payslip.company_id.country_id.code != 'BE':
        continue

    is_december = payslip.date_from.month == 12
    departure_date = payslip.employee_id.departure_date
    is_departure = bool(
        departure_date and payslip.date_from <= departure_date <= payslip.date_to
    )

    if not (is_december or is_departure):
        continue

    net_to_recover_amount = payslip._get_line_values(['NET_TO_RECOVER'], compute_sum=True)['NET_TO_RECOVER']['sum']['total']

    if net_to_recover_amount > 0:
        formatted_amount = f"{net_to_recover_amount:.2f}"

        if is_december and is_departure:
            message = _get_payroll_translation("December departure payslip has an unrecovered net amount of %(amount)s.", amount=formatted_amount)
        elif is_december:
            message = _get_payroll_translation("December payslip has an unrecovered net amount of %(amount)s.", amount=formatted_amount)
        else:
            message = _get_payroll_translation("Departure payslip has an unrecovered net amount of %(amount)s.", amount=formatted_amount)

        warning_details[payslip].append({
            'message': message,
            'level': 'warning',
        })
        warning_records |= payslip

be_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'BE')
employee_type = self.env.ref('hr.contract_type_employee', raise_if_not_found=False)
today = date.today()
try:
    threshold_date = today.replace(year=today.year - 18)
except ValueError:
    threshold_date = today.replace(year=today.year - 18, day=28)
employee_versions_under_18 = self.env['hr.version'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', be_companies.ids),
    ('employee_type_id', '=', employee_type.id if employee_type else False),
    ('employee_id.birthday', '!=', False),
    ('employee_id.birthday', '>', threshold_date),
])
warning_records = self.env['hr.version']
warning_details = defaultdict(list)
if employee_versions_under_18:
    warning_records |= employee_versions_under_18
    for employee in employee_versions_under_18:
        warning_details[employee].append({
            'message': _get_payroll_translation("The employee is under the legal minimum working age (18 years old)"),
            'level': 'danger',
        })

be_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'BE')
student_employee_type = self.env.ref('hr.contract_type_student', raise_if_not_found=False)
today = date.today()
try:
    threshold_date = today.replace(year=today.year - 15)
except ValueError:
    threshold_date = today.replace(year=today.year - 15, day=28)
student_versions_under_15 = self.env['hr.version'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', be_companies.ids),
    ('employee_type_id', '=', student_employee_type.id if student_employee_type else False),
    ('employee_id.birthday', '!=', False),
    ('employee_id.birthday', '>', threshold_date),
])
warning_records = self.env['hr.version']
warning_details = defaultdict(list)
if student_versions_under_15:
    warning_records |= student_versions_under_15
    for employee in student_versions_under_15:
        warning_details[employee].append({
            'message': _get_payroll_translation("The student is under the legal minimum working age (15 years old)"),
            'level': 'danger',
        })

december_payslips = records.filtered(lambda slip: slip.l10n_be_is_december)
warning_records = self.env['hr.payslip']
warning_details = defaultdict(list)

if december_payslips:
    employees = december_payslips.employee_id
    reference_year = december_payslips[0].date_from.year
    leaves_to_postpone_by_employee = self.env['hr.payroll.alloc.paid.leave']._get_paid_time_off_to_postpone_by_employee(
        employees, reference_year
    )

    postponements = (
        ('postpone_n1', 'PPTO1', [1, 0],
        "%(days)s days of Paid time off remaining.\nThe employee was sick in december and couldn't take all paid time off. You can decide to postpone them for next year."),
        ('postpone_n2', 'PPTO2', [0, 1],
        "%(days)s days of Postponed off remaining.\nThe employee was sick during all this year and couldn't take the paid time off postponed from the previous year. You can decide to postpone them again to next year."),
    )

    for payslip in december_payslips:
        employee = payslip.employee_id
        leaves_to_postpone = leaves_to_postpone_by_employee[employee]

        input_amounts = {'PPTO1': 0, 'PPTO2': 0}
        for line in payslip.input_line_ids:
            if line.code in input_amounts:
                input_amounts[line.code] += line.amount

        for postponement_type, input_code, action_ratio, message in postponements:
            existing_amount = input_amounts[input_code]
            remaining_days = max(0, leaves_to_postpone[postponement_type] - existing_amount)
            if not remaining_days:
                continue

            warning_records |= payslip
            warning_details[payslip].append({
                'message': _get_payroll_translation(message, days=f"{remaining_days:g}"),
                'level': 'warning',
                'action_text': _get_payroll_translation("Postpone"),
                'action': {
                    'type': 'object',
                    'name': 'action_postpone_paid_time_off',
                    'args': json.dumps([remaining_days * ratio for ratio in action_ratio]),
                },
            })

belgian_companies = self.env.companies.filtered(lambda c: c.country_id.code == 'BE')
if belgian_companies:
    reference_year = date.today().year
    is_december_run_done = bool(self.env['hr.payslip.run'].search_count([
        ('company_id', 'in', belgian_companies.ids),
        ('date_start', '<=', date(reference_year, 12, 31)),
        ('date_end', '>=', date(reference_year, 12, 1)),
        ('state', 'in', ('02_close', '03_paid')),
    ]))
    if is_december_run_done:
        wizard = self.env['hr.payroll.alloc.paid.leave'].new({ 'year': str(reference_year) })
        warning_records = self.env['hr.employee']
        for employee, data in wizard._get_allocation_data().items():
            expected_allocation = data.get('expected_paid_time_off_to_allocate', 0)
            already_allocated = data.get('already_allocated_paid_time_off', 0)
            if float_compare(expected_allocation, already_allocated, precision_digits=2) != 0:
                warning_records |= employee

        if warning_records:
            warning_title = _get_payroll_translation(
                "Employees require paid time off allocation for %(year)s",
                year=reference_year + 1
            )
            warning_action = self.env.ref('l10n_be_hr_payroll.allocating_paid_time_off_wizard_action')._get_action_dict()
            warning_action['context'] = {'default_employee_ids': warning_records.ids}
